  const [trialBalance,setTrialBalance]=useState<LedgerTrialBalance|null>(null),[trialFrom,setTrialFrom]=useState(''),[trialTo,setTrialTo]=useState('')
  const [balanceSheet,setBalanceSheet]=useState<BalanceSheet|null>(null),[balanceSheetDate,setBalanceSheetDate]=useState(localDateString())
  const [incomeStatement,setIncomeStatement]=useState<IncomeStatement|null>(null),[incomeFrom,setIncomeFrom]=useState(`${new Date().getFullYear()}-01-01`),[incomeTo,setIncomeTo]=useState(localDateString())
  const [manualDate,setManualDate]=useState(localDateString()),[manualDescription,setManualDescription]=useState(''),[manualLines,setManualLines]=useState([{accountId:'',description:'',debit:'0',credit:'0'},{accountId:'',description:'',debit:'0',credit:'0'}])
  const [editingAccountId,setEditingAccountId]=useState(''),[editingAccountCode,setEditingAccountCode]=useState(''),[editingAccountName,setEditingAccountName]=useState(''),[editingAccountSection,setEditingAccountSection]=useState<LedgerStatementSection>('Unclassified')
  const [sources,setSources]=useState<{salesInvoices:LedgerSource[];salesDeliveries:LedgerSource[];purchaseInvoices:LedgerSource[];purchaseReceipts:LedgerSource[];salesReturns:LedgerSource[];supplierReturns:LedgerSource[];customerCollections:LedgerSource[];supplierPayments:LedgerSource[];fxRevaluations:LedgerSource[];inventoryAdjustments:LedgerSource[]}>({salesInvoices:[],salesDeliveries:[],purchaseInvoices:[],purchaseReceipts:[],salesReturns:[],supplierReturns:[],customerCollections:[],supplierPayments:[],fxRevaluations:[],inventoryAdjustments:[]})
  const [selected,setSelected]=useState<JournalEntryView|null>(null)
  const [code,setCode]=useState(''),[name,setName]=useState(''),[newAccountSection,setNewAccountSection]=useState<LedgerStatementSection>('Unclassified'),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false)
  const labelByKey=Object.fromEntries(mappings.map(m=>[m.mappingKey,m.label])) as Record<string,string>
  const readyMappings=mappings.filter(m=>m.accountId&&accounts.some(a=>a.id===m.accountId&&a.isActive)).length
  function missingFor(source:LedgerSource){return source.requiredMappings.filter(key=>!mappings.some(m=>m.mappingKey===key&&m.accountId&&accounts.some(a=>a.id===m.accountId&&a.isActive)))}
  async function load(targetPage=entryPage){try{const entryParams=new URLSearchParams({page:String(targetPage),pageSize:'50'});if(entryFrom)entryParams.set('from',entryFrom);if(entryTo)entryParams.set('to',entryTo);const [a,m,e,s,t]=await Promise.all([api<LedgerAccount[]>('/api/finance/general-ledger/accounts',token),api<LedgerMapping[]>('/api/finance/general-ledger/mappings',token),api<{items:JournalEntrySummary[];page:number;pageSize:number;total:number}>(`/api/finance/general-ledger/entries?${entryParams}`,token),api<typeof sources>('/api/finance/general-ledger/sources',token),api<LedgerTrialBalance>('/api/finance/general-ledger/trial-balance',token)]);setAccounts(a);setMappings(m);setEntries(e.items);setEntryTotal(e.total);setSources(s);setTrialBalance(t)}catch(e){setError((e as Error).message)}}
  function applyEntryFilters(){setEntryPage(1);void load(1)}
  async function loadTrialBalance(){setError('');setTrialBalance(null);try{const params=new URLSearchParams();if(trialFrom)params.set('from',trialFrom);if(trialTo)params.set('to',trialTo);setTrialBalance(await api<LedgerTrialBalance>(`/api/finance/general-ledger/trial-balance${params.size?`?${params}`:''}`,token))}catch(e){setError((e as Error).message)}}
  async function loadBalanceSheet(){setError('');setBalanceSheet(null);try{const params=new URLSearchParams({asOfDate:balanceSheetDate});setBalanceSheet(await api<BalanceSheet>(`/api/finance/general-ledger/financial-statements/balance-sheet?${params}`,token))}catch(e){setError((e as Error).message)}}
  async function loadIncomeStatement(){setError('');setIncomeStatement(null);try{const params=new URLSearchParams({from:incomeFrom,to:incomeTo});setIncomeStatement(await api<IncomeStatement>(`/api/finance/general-ledger/financial-statements/income-statement?${params}`,token))}catch(e){setError((e as Error).message)}}
  function exportTrialBalance(){if(!trialBalance)return;const cell=(value:unknown)=>`"${String(value??'').replace(/"/g,'""')}"`;const rows=[['Hesap kodu','Hesap adı','Açılış borç','Açılış alacak','Dönem borç','Dönem alacak','Kapanış borç','Kapanış alacak'],...trialBalance.accounts.map(row=>[row.code,row.name,row.openingDebit,row.openingCredit,row.debit,row.credit,row.balanceDebit,row.balanceCredit]),['Toplam','','','','','','',''],['Açılış toplamı','',trialBalance.totalOpeningDebit,trialBalance.totalOpeningCredit,'','','',''],['Dönem hareketi','','','',trialBalance.totalDebit,trialBalance.totalCredit,'',''],['Kapanış bakiyesi','','','','','',trialBalance.totalBalanceDebit,trialBalance.totalBalanceCredit]];const csv='\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`mizan-${trialFrom||'baslangic'}-${trialTo||'bugun'}.csv`;link.click();URL.revokeObjectURL(url)}
  useEffect(()=>{void load()},[token,entryPage])
  async function createAccount(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await api('/api/finance/general-ledger/accounts',token,{method:'POST',body:JSON.stringify({code,name,isActive:true,statementSection:newAccountSection})});setCode('');setName('');setNotice('Hesap eklendi. Hesap eşleştirmelerini ayrıca tanımlayın.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
