  async function saveAccount(account:LedgerAccount,isActive=account.isActive,code=editingAccountCode,name=editingAccountName,statementSection=editingAccountSection){setBusy(true);setError('');try{await api(`/api/finance/general-ledger/accounts/${account.id}`,token,{method:'PUT',body:JSON.stringify({code,name,isActive,statementSection})});setEditingAccountId('');setNotice('Hesap güncellendi.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function toggleAccount(account:LedgerAccount){await saveAccount(account,!account.isActive,account.code,account.name,account.statementSection)}
  async function mapAccount(key:string,accountId:string){if(!accountId)return;const previous=mappings.find(m=>m.mappingKey===key)?.accountId;if(previous&&previous!==accountId&&!window.confirm('Bu eşleştirme sonraki aktarımlarda kullanılacak. Daha önce oluşturulmuş yevmiye fişleri değişmez. Devam edilsin mi?'))return;setBusy(true);setError('');try{await api(`/api/finance/general-ledger/mappings/${encodeURIComponent(key)}`,token,{method:'PUT',body:JSON.stringify({mappingKey:key,accountId})});setNotice('Hesap eşleştirmesi kaydedildi.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function transfer(sourceType:'SalesInvoice'|'SalesDelivery'|'PurchaseInvoice'|'PurchaseReceipt'|'SalesReturn'|'SupplierReturn'|'CustomerCollection'|'SupplierPayment'|'FxRevaluation'|'InventoryCostAdjustment',source:LedgerSource){if(missingFor(source).length||source.amount<=0)return;if(!window.confirm(`${source.code} kaynağı değiştirilemez yevmiye fişi olarak aktarılsın mı? Borç ve alacak hesaplarını kontrol ettiğinizi onaylayın.`))return;setBusy(true);setError('');setNotice('');try{const result=await api<JournalEntrySummary>('/api/finance/general-ledger/transfer',token,{method:'POST',body:JSON.stringify({sourceType,sourceId:source.id})});setNotice(`${result.code} yevmiye fişi oluşturuldu. Borç ve alacak toplamı ${result.totalDebit.toLocaleString('tr-TR',{minimumFractionDigits:2})}.`);await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function createManualEntry(e:React.FormEvent){e.preventDefault();const debit=manualLines.reduce((sum,line)=>sum+Number(line.debit||0),0),credit=manualLines.reduce((sum,line)=>sum+Number(line.credit||0),0);if(debit<=0||debit!==credit){setError('Borç ve alacak toplamları eşit ve sıfırdan büyük olmalı.');return}setBusy(true);setError('');setNotice('');try{const result=await api<JournalEntrySummary>('/api/finance/general-ledger/entries/manual',token,{method:'POST',body:JSON.stringify({entryDate:manualDate,description:manualDescription,lines:manualLines.map(line=>({...line,debit:Number(line.debit),credit:Number(line.credit)}))})});setManualDescription('');setManualLines([{accountId:'',description:'',debit:'0',credit:'0'},{accountId:'',description:'',debit:'0',credit:'0'}]);setNotice(`${result.code} manuel yevmiye fişi kaydedildi.`);await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
