  async function reverseJournalEntry(entry:JournalEntryView){const reason=window.prompt(`${entry.code} fişi için ters kayıt gerekçesi:`)?.trim();if(!reason)return;if(!window.confirm(`${entry.code} fişinin borç/alacak satırları ${reason} gerekçesiyle ters çevrilsin mi?`))return;setBusy(true);setError('');setNotice('');try{const reversal=await api<JournalEntrySummary>(`/api/finance/general-ledger/entries/${entry.id}/reverse`,token,{method:'POST',body:JSON.stringify({entryDate:localDateString(),reason})});setNotice(`${reversal.code} ters kayıt oluşturuldu.`);setSelected(null);await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
